const { withAppBuildGradle } = require('@expo/config-plugins');

// Production Android release builds (net.quranquiz) are signed with the real
// Play Store key, not the debug keystore CNG wires up by default — see the
// project-android-release-signing memory / README. android/ is gitignored
// CNG output, regenerated by `expo prebuild` on every build, so this has to
// be a config plugin rather than a one-off manual edit to
// android/app/build.gradle: otherwise a clean prebuild silently reverts the
// "release" build type back to debug-signed with no error.
//
// No secret is written to disk by this plugin. Gradle reads the keystore
// path/passwords/alias from QQ_RELEASE_* env vars at build time (set by
// scripts/release.sh), falling back to the debug keystore so local dev
// builds (`expo run:android`, `./gradlew assembleDebug`) are unaffected.
const SIGNING_MARKER = '// @generated withAndroidReleaseSigning';

// Anchor text taken verbatim from the CNG-generated template (React
// Native's default android/app/build.gradle). If a future Expo/RN upgrade
// changes this template, the plugin throws instead of silently leaving the
// release build type debug-signed.
const DEBUG_SIGNING_CONFIG = `        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }`;

const RELEASE_SIGNING_CONFIG = `${DEBUG_SIGNING_CONFIG}
        release {
            ${SIGNING_MARKER}
            storeFile file(System.getenv("QQ_RELEASE_STORE_FILE") ?: "debug.keystore")
            storePassword System.getenv("QQ_RELEASE_STORE_PASSWORD") ?: "android"
            keyAlias System.getenv("QQ_RELEASE_KEY_ALIAS") ?: "androiddebugkey"
            keyPassword System.getenv("QQ_RELEASE_KEY_PASSWORD") ?: "android"
        }`;

// Matches only the release buildType's `signingConfig signingConfigs.debug`
// line (anchored on the comment that precedes it in the template), not the
// debug buildType's identical-looking line elsewhere in the file.
const RELEASE_BUILD_TYPE_SIGNING =
  /(\/\/ Caution! In production, you need to generate your own keystore file\.\s*\n\s*\/\/ see https:\/\/reactnative\.dev\/docs\/signed-apk-android\.\s*\n\s*signingConfig )signingConfigs\.debug/;

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    let contents = config.modResults.contents;
    if (contents.includes(SIGNING_MARKER)) return config;

    if (!contents.includes(DEBUG_SIGNING_CONFIG)) {
      throw new Error(
        'withAndroidReleaseSigning: could not find the expected debug signingConfig block in ' +
          'android/app/build.gradle — the CNG template may have changed, update the plugin\'s anchor text.'
      );
    }
    contents = contents.replace(DEBUG_SIGNING_CONFIG, RELEASE_SIGNING_CONFIG);

    if (!RELEASE_BUILD_TYPE_SIGNING.test(contents)) {
      throw new Error(
        'withAndroidReleaseSigning: could not find the release buildType\'s signingConfig line in ' +
          'android/app/build.gradle — the CNG template may have changed, update the plugin\'s anchor text.'
      );
    }
    contents = contents.replace(RELEASE_BUILD_TYPE_SIGNING, '$1signingConfigs.release');

    config.modResults.contents = contents;
    return config;
  });
};
